// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        // Ensure the caller is not the owner (to avoid owner-only interactions affecting result)
        vm.assume(caller != address(this)); // owner is this contract in forge test

        // Call logSetupFailed as the given caller
        bool result = c.logSetupFailed();

        // The general rule: if the caller is not an approved logger, the result should be false
        // We use the public getter to check approval status before the call
        bool isApproved = c.approvedToLog(caller);

        // The reference satisfies: result == isApproved
        // The mutation breaks this because it always returns true regardless of isApproved
        assertTrue(result == isApproved, "logSetupFailed should return approval status");
    }
}

